//! Fixed release identities, one Vault per invocation and no absolute path.
use super::definitions::entry;
use super::{AgentBuiltinEntry, AgentBuiltinHandler as H, BuiltinToolDefinitionSetError};
use aura_domain_common::UtcTimestamp;
use aura_memory_domain::*;
use aura_security_contract::ResolvedCapability as C;

pub(super) fn entries(
    at: UtcTimestamp,
) -> Result<Vec<AgentBuiltinEntry>, BuiltinToolDefinitionSetError> {
    vec![
        entry::<MemorySearchInput,MemorySearchResult>(45,H::MemorySearch,"Search one Memory Vault","Search this session's project or the global Memory Vault. scope is required: project or global. Search each separately when both matter. Chinese short queries are supported. Optional category and limit (1..100); inactive notes are excluded unless include_inactive=true. Memory may be stale: verify against current workspace facts. Incomplete indexing is disclosed. No absolute path or other workspace can be supplied.",&[C::MemoryRead],false,at),
        entry::<MemoryReadInput,MemoryRead>(46,H::MemoryRead,"Read a memory by stable ID or Vault path","Read target={kind:id,id} or {kind:path,scope:project|global,path:<Vault-relative Markdown path>}. IDs survive renames. Returns note, BLAKE3 hash and metadata-only history. If an ID exists in both Vaults use scope and path. Never accepts absolute paths or another workspace.",&[C::MemoryRead],false,at),
        entry::<MemoryRecentInput,MemorySearchResult>(47,H::MemoryRecent,"List recent memories","List recallable memories in one scope (project or global), ordered by recall and recency. limit is 1..100. Archived, forgotten, superseded and invalid notes are not returned by default. Search/read results enter the current turn; there is no fixed Memory context section.",&[C::MemoryRead],false,at),
        entry::<MemoryCreateInput,MemoryMutationResult>(48,H::MemoryCreate,"Create memories atomically","Create 1..100 notes in one scope. Each item supplies a Vault-relative .md path, category and Markdown body; stable IDs and provenance are generated by Core. Never store secrets, transient details or unverified claims. Entire batch is validated before writing; conflicts or unsafe paths reject it. Returns IDs, paths and new BLAKE3 hashes. WorkspaceReadWrite and FullAccess allow writes in both Vaults; ReadOnly asks once or for the session.",&[C::MemoryWrite],true,at),
        entry::<MemoryUpdateInput,MemoryMutationResult>(49,H::MemoryUpdate,"Update memories with expected hashes","Update 1..100 notes atomically in one scope. Each target is {kind:id,id} or {kind:path,path}; expected_hash is the current lowercase BLAKE3 hash from memory.read. Omitted patch fields are unchanged. A stale hash rejects the batch and reports the current hash. supersedes_ids also marks the old notes superseded atomically. Stable IDs and creation time are retained. Prefer update, supersede, forget or archive over deletion. Never store secrets.",&[C::MemoryWrite],true,at),
        entry::<MemoryLinkInput,MemoryMutationResult>(50,H::MemoryLink,"Link notes inside one Vault","Link source and target stable IDs in this scope using related, supersedes or conflicts. Cross-Vault and missing targets are rejected. Conflict links mark both notes conflicted and expose the relationship; supersedes marks the old note superseded. No external path or cross-project lookup.",&[C::MemoryWrite],true,at),
        entry::<MemoryStateInput,MemoryMutationResult>(51,H::MemoryForget,"Forget memories without deleting files","Mark targets forgotten in one Vault. Files and metadata-only history remain. Targets are stable IDs or Vault-relative paths. Uses current hashes under the single writer and never overwrites a concurrent external edit. This is a normal Memory write, with ReadOnly approval.",&[C::MemoryWrite],true,at),
        entry::<MemoryStateInput,MemoryMutationResult>(52,H::MemoryArchive,"Archive memories without deleting files","Mark targets archived in one Vault. Files and metadata-only history remain; default recall excludes them. Prefer this over permanent deletion. Targets cannot name another Vault or workspace.",&[C::MemoryWrite],true,at),
        entry::<MemoryDeleteInput,MemoryMutationResult>(53,H::MemoryDelete,"Delete memories after one-time approval","Permanently delete 1..100 notes in one Vault after a single approval for the entire batch. Every item requires expected_hash from memory.read. ALWAYS asks in every mode, with Allow once or Deny only. A stale hash rejects the whole batch. Metadata-only history retains hashes and titles, never bodies. Prefer update, supersede, forget or archive.",&[C::MemoryDelete],true,at),
        entry::<MemoryScopeInput,MemoryValidation>(54,H::MemoryValidate,"Validate a Vault without changing its notes","Validate files and rebuild derived metadata only. Report invalid YAML/schema, duplicate IDs and unsafe paths. Never overwrite or delete invalid user files. Use repair preview, or open the Vault in Obsidian to fix semantics manually.",&[C::MemoryRead],false,at),
        entry::<MemoryRepairInput,MemoryRepairResult>(55,H::MemoryRepair,"Preview and apply structural Memory repairs","Use phase=preview first. It does not change Vault files and reports exact paths/hashes, missing metadata defaults, missing README and manual work. Apply with this session's preview_token; stale files or another owner invalidate it. Apply is MemoryWrite and follows the write approval matrix. Repair never rewrites Markdown meaning, deletes duplicate IDs or restores an owner's deliberately removed .gitignore. Indexes can be rebuilt.",&[C::MemoryRead],true,at),
    ].into_iter().collect()
}
